import mongoose, { Schema } from 'mongoose';

// User Schema
const UserSchema = new Schema({
  name: { type: String, required: true },
  email: { type: String, required: true, unique: true },
  passwordHash: { type: String, required: true },
  role: { type: String, enum: ['admin', 'client'], default: 'client' },
  company: { type: String },
  phone: { type: String },
}, { timestamps: true });

// Milestone Sub-Schema
const MilestoneSchema = new Schema({
  status: { type: String, required: true },
  title: { type: String, required: true },
  location: { type: String, required: true },
  city: { type: String, required: true },
  country: { type: String, required: true },
  timestamp: { type: Date, default: Date.now },
  notes: { type: String },
  operator: { type: String },
  completed: { type: Boolean, default: true },
  lat: { type: Number },
  lng: { type: Number },
});

// Shipment Schema
const ShipmentSchema = new Schema({
  trackingNumber: { type: String, required: true, unique: true, index: true },
  consignmentNumber: { type: String, required: true, unique: true },
  title: { type: String, required: true },
  status: { 
    type: String, 
    enum: ['Pending', 'Picked Up', 'In Transit', 'Customs Clearance', 'Out for Delivery', 'Delivered', 'Exception'],
    default: 'Pending',
    index: true
  },
  serviceType: { type: String, required: true },
  userId: { type: Schema.Types.ObjectId, ref: 'User', index: true },
  sender: {
    name: String,
    company: String,
    email: String,
    phone: String,
    street: String,
    city: String,
    postalCode: String,
    country: String,
  },
  recipient: {
    name: String,
    company: String,
    email: String,
    phone: String,
    street: String,
    city: String,
    postalCode: String,
    country: String,
  },
  originHub: {
    name: String,
    city: String,
    country: String,
    code: String,
    lat: Number,
    lng: Number,
  },
  destinationHub: {
    name: String,
    city: String,
    country: String,
    code: String,
    lat: Number,
    lng: Number,
  },
  currentLocation: {
    name: String,
    city: String,
    country: String,
    lat: Number,
    lng: Number,
  },
  cargoDetails: {
    pieces: Number,
    weightKg: Number,
    volumeCbm: Number,
    declaredValueUsd: Number,
    cargoType: String,
    dimensions: { lengthCm: Number, widthCm: Number, heightCm: Number },
    dangerousGoods: Boolean,
    temperatureControlled: Boolean,
    temperatureRange: String,
  },
  carrier: {
    name: String,
    serviceLevel: String,
    vesselOrFlight: String,
    sealNumber: String,
    contactNumber: String,
  },
  milestones: [MilestoneSchema],
  estimatedDelivery: { type: Date, required: true },
  actualDelivery: { type: Date },
  signatureRequired: { type: Boolean, default: false },
  notes: { type: String },
}, { timestamps: true });

export const UserModel = mongoose.models.User || mongoose.model('User', UserSchema);
export const ShipmentModel = mongoose.models.Shipment || mongoose.model('Shipment', ShipmentSchema);
